import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "./utils"

/**
 * Base UI vs Radix slider — value shape divergence.
 *
 * Base UI's `onValueChange` calls back with a SINGLE NUMBER for a single-thumb
 * slider, and a `number[]` only when 2+ thumbs are present (see
 * `resolveThumbCollision` in @base-ui/react/slider — it recomputes
 * `range = activeValues.length > 1` internally). Radix (the shadcn default)
 * always hands back an array. Every call site in this app uses the array
 * convention: `onValueChange={([v]) => ...}`. Without normalization, dragging
 * a one-thumb slider throws `number X is not iterable` and the thumb stays
 * stuck because the consumer's setter never runs.
 *
 * The wrapper:
 *   • Accepts `value` / `defaultValue` as `number | number[]` (forwards as-is
 *     to Base UI so it can compute thumb positions correctly).
 *   • Overrides the `onValueChange` PROP TYPE to the Radix-style
 *     `(value: number[], details) => void` so call sites can destructure
 *     `([v]) => ...` without per-site casts.
 *   • Wraps `onValueChange` at runtime to ALWAYS pass a `number[]` to the
 *     consumer, matching the overridden type.
 */
type SliderProps = Omit<SliderPrimitive.Root.Props, "onValueChange"> & {
  /** Always receives a `number[]` (Radix convention), even for single-thumb
   *  sliders where Base UI would otherwise pass a bare number. */
  onValueChange?: (value: number[], details: unknown) => void
}

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  onValueChange,
  ...props
}: SliderProps) {
  // Render one thumb per value entry. Accept either a single number or an
  // array from the caller; Base UI accepts both.
  const valuesForThumbs = Array.isArray(value)
    ? value
    : Array.isArray(defaultValue)
      ? defaultValue
      : [min, max]

  // Normalize the change callback so consumers always receive `number[]`,
  // even when Base UI calls back with a bare number (single-thumb case).
  const handleValueChange = React.useCallback(
    (next: number | readonly number[], details: unknown) => {
      if (!onValueChange) return
      const arr = Array.isArray(next) ? [...next] : [next]
      onValueChange(arr, details)
    },
    [onValueChange],
  )

  return (
    <SliderPrimitive.Root
      className={cn("w-full data-[orientation=vertical]:h-full", className)}
      data-slot="slider"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      thumbAlignment="edge"
      onValueChange={handleValueChange}
      {...props}
    >
      <SliderPrimitive.Control className="relative flex w-full touch-none items-center select-none data-disabled:opacity-50 data-[orientation=vertical]:h-full data-[orientation=vertical]:min-h-40 data-[orientation=vertical]:w-auto data-[orientation=vertical]:flex-col">
        <SliderPrimitive.Track
          data-slot="slider-track"
          className="relative grow overflow-hidden rounded-full bg-muted select-none h-1 w-full data-[orientation=vertical]:h-full data-[orientation=vertical]:w-1"
        >
          <SliderPrimitive.Indicator
            data-slot="slider-range"
            className="bg-primary select-none h-full w-full"
          />
        </SliderPrimitive.Track>
        {Array.from({ length: valuesForThumbs.length }, (_, index) => (
          <SliderPrimitive.Thumb
            data-slot="slider-thumb"
            key={index}
            className="relative block size-3 shrink-0 rounded-full border border-ring bg-white ring-ring/50 transition-[color,box-shadow] select-none after:absolute after:-inset-2 hover:ring-3 focus-visible:ring-3 focus-visible:outline-hidden active:ring-3 disabled:pointer-events-none disabled:opacity-50"
          />
        ))}
      </SliderPrimitive.Control>
    </SliderPrimitive.Root>
  )
}

export { Slider }
